-- ============================================================================
-- TinOR V3.3 — Import des registres Excel Jardins de Jerba (historique complet)
-- Graines (Eco-Land, Napoliss) → presse → filtration → mélanges (lots finis)
-- → conditionnements (flacons) → ventes, avec n° de lot et dates d'origine.
-- 82 lots · 19 conditionnements · 212 mouvements de stock.
--
-- À exécuter UNE fois dans la base RÉEL (ex. tinor_reel), après avoir démarré
-- TinOR au moins une fois avec la dernière version (tables à jour).
-- Si un lot des registres existe déjà, le script s'arrête sans rien modifier.
-- Produit par scripts/registres-en-sql.js — ne pas modifier à la main.
-- ============================================================================
SET NAMES utf8mb4;

DELIMITER //
BEGIN NOT ATOMIC
  IF EXISTS (SELECT 1 FROM lots WHERE numero_lot IN ('2314', 'GJ01/2023', '2313', '2312', '01-2314-20231217H', '02-2314-20231218H', '03-GJ01/2023-20231218H', '04-GJ01/2023-20231219H', '05-GJ01/2023-20231224H', '06-GJ01/2023-20231225H', '07-GJ01/2023-20231226H', '08-GJ01/2023-20240210H', '08-2313-20240210H', '09-2313-20240211H', '10-2313-20240217H', '11-2313-20240318H', '12-2313-20240319H', '13-2313-20240320H', '14-GJ01/2023-20240320H', '15-GJ01/2023-20240321H', '16-GJ01/2023-20240323H', '17-GJ01/2023-20240324H', '18-GJ01/2023-20240325H', '19-GJ01/2023-20240326H', '20-GJ01/2023-20240327H', '21-GJ01/2023-20240328H', '22-GJ01/2023-20240329H', '23-2312-20240331H', '24-2312-20240407H', '25-2312-20240427H', '26-2312-20240428H', '27-2312-20240505H', '28-2312-20240506H', '29-2312-20240702H', '01-2314-20231217', '05-GJ01/2023-20231224', '15-GJ01/2023-20240321', '18-GJ01/2023-20240325', '23-2312-20240331', '24-2312-20240407', '25-2312-20240427', '27-2312-20240505', '28-2312-20240506', '29-2312-20240711', '02-2314-20241009', '08-GJ01/2023-20241105', '08-2313-20241105', '03-GJ01/2023-20250115', '08-GJ01/2023-20250122', '08-2313-20250123', '04-GJ01/2023-20251020', '09-2313-20251021', '11-2313-20251023', '19-GJ01/2023-20251026', '20-GJ01/2023-20251028', '10-2313-20251103', '06-GJ01/2023-20251105', '011823', '021825', '030808', '042505', '050502', '061803', '070324', '082415', '090808', '100106', '011823-10ML', '021825-10ML', '021825-30ML', '042505-30ML', '050502-30ML', '061803-30ML', '070324-30ML', '082415-30ML', '082415-10ML', '090808-30ML', '090808-10ML', '030808-30ML', '030808-10ML', '100106-30ML', '100106-10ML')) THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Import deja fait : des lots des registres existent deja dans la base. Rien n''est modifie.';
  END IF;
END //
DELIMITER ;

START TRANSACTION;

-- Fournisseurs (créés s'ils n'existent pas)
  WHERE NOT EXISTS (SELECT 1 FROM fournisseurs WHERE nom = 'Eco-Land');
  WHERE NOT EXISTS (SELECT 1 FROM fournisseurs WHERE nom = 'Napoliss');

-- Produits (créés s'ils n'existent pas ; code = suivant libre)
  SELECT (SELECT LPAD(COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1, 2, '0') FROM produits x), 'Pépins de figue de barbarie',
    (SELECT id FROM categories WHERE code = 'HUILE' ORDER BY id LIMIT 1), (SELECT id FROM unites WHERE code = 'kg' ORDER BY id LIMIT 1),
    NULL, 'MATIERE_PREMIERE',
    NULL, 0, 0, 1, 1, 0, 19
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM produits z WHERE nom = 'Pépins de figue de barbarie');
  SELECT (SELECT LPAD(COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1, 2, '0') FROM produits x), 'Huile de pépins de figue de barbarie — Vrac',
    (SELECT id FROM categories WHERE code = 'HUILE' ORDER BY id LIMIT 1), (SELECT id FROM unites WHERE code = 'litre' ORDER BY id LIMIT 1),
    NULL, 'PRODUIT_FABRIQUE',
    NULL, 0, 1, 1, 1, 0, 19
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM produits z WHERE nom = 'Huile de pépins de figue de barbarie — Vrac');
  SELECT (SELECT LPAD(COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1, 2, '0') FROM produits x), 'Huile de pépins de figue de barbarie — Filtrée',
    (SELECT id FROM categories WHERE code = 'HUILE' ORDER BY id LIMIT 1), (SELECT id FROM unites WHERE code = 'litre' ORDER BY id LIMIT 1),
    NULL, 'PRODUIT_FABRIQUE',
    (SELECT id FROM produits y WHERE nom = 'Huile de pépins de figue de barbarie — Vrac' ORDER BY id LIMIT 1), 0, 1, 1, 1, 0, 19
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM produits z WHERE nom = 'Huile de pépins de figue de barbarie — Filtrée');
  SELECT (SELECT LPAD(COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1, 2, '0') FROM produits x), 'Huile de pépins de figue de barbarie — Flacon 10ml',
    (SELECT id FROM categories WHERE code = 'HUILE' ORDER BY id LIMIT 1), (SELECT id FROM unites WHERE code = 'unite' ORDER BY id LIMIT 1),
    (SELECT id FROM formats WHERE volume = 10 ORDER BY id LIMIT 1), 'PRODUIT_FABRIQUE',
    (SELECT id FROM produits y WHERE nom = 'Huile de pépins de figue de barbarie — Filtrée' ORDER BY id LIMIT 1), 1, 1, 1, 1, 0, 19
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM produits z WHERE nom = 'Huile de pépins de figue de barbarie — Flacon 10ml');
  SELECT (SELECT LPAD(COALESCE(MAX(CAST(code AS UNSIGNED)), 0) + 1, 2, '0') FROM produits x), 'Huile de pépins de figue de barbarie — Flacon 30ml',
    (SELECT id FROM categories WHERE code = 'HUILE' ORDER BY id LIMIT 1), (SELECT id FROM unites WHERE code = 'unite' ORDER BY id LIMIT 1),
    (SELECT id FROM formats WHERE volume = 30 ORDER BY id LIMIT 1), 'PRODUIT_FABRIQUE',
    (SELECT id FROM produits y WHERE nom = 'Huile de pépins de figue de barbarie — Filtrée' ORDER BY id LIMIT 1), 1, 1, 1, 1, 0, 19
  FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM produits z WHERE nom = 'Huile de pépins de figue de barbarie — Flacon 30ml');

-- Décalage des identifiants après ceux déjà présents dans la base
SET @L := (SELECT COALESCE(MAX(id), 0) FROM lots);
SET @P := (SELECT COALESCE(MAX(id), 0) FROM lots_presse);
SET @F := (SELECT COALESCE(MAX(id), 0) FROM lots_filtration);
SET @R := (SELECT COALESCE(MAX(id), 0) FROM receptions);
SET @C := (SELECT COALESCE(MAX(id), 0) FROM conditionnements);
SET @NR := COALESCE((SELECT `last_value` FROM sequences WHERE name = 'reception_seq'), 0);
SET @NM := COALESCE((SELECT `last_value` FROM sequences WHERE name = 'mouvement_seq'), 0);
SET @LOCAL := (SELECT MIN(id) FROM locaux);

